void seed_default_apps(lfs_t *lfs) {
    if (!lfs) return;
    struct lfs_info info;
    if (lfs_stat(lfs, "/apps/servo-master/app.json", &info) == 0) {
        return; /* Already seeded */
    }
    lfs_mkdir(lfs, "/apps");
    lfs_mkdir(lfs, "/apps/servo-master");
    lfs_file_t f;
    if (lfs_file_open(lfs, &f, "/apps/servo-master/app.json", LFS_O_WRONLY | LFS_O_CREAT | LFS_O_TRUNC) >= 0) {
        lfs_file_write(lfs, &f, servo_master_app_json, sizeof(servo_master_app_json));
        lfs_file_close(lfs, &f);
    }
    if (lfs_file_open(lfs, &f, "/apps/servo-master/index.html", LFS_O_WRONLY | LFS_O_CREAT | LFS_O_TRUNC) >= 0) {
        lfs_file_write(lfs, &f, servo_master_index_html, sizeof(servo_master_index_html));
        lfs_file_close(lfs, &f);
    }
}
